package blockbranch.realistic;
import java.nio.file.*;import java.util.*;import net.minecraft.core.*;import net.minecraft.core.registries.Registries;import net.minecraft.world.level.block.Blocks;
public final class WetlandHutLegacyQualification {
 public static void register(){net.fabricmc.fabric.api.event.lifecycle.v1.ServerLifecycleEvents.SERVER_STARTED.register(server->{try{
  var l=server.overworld();var g=(RealisticGenerator)l.getChunkSource().getGenerator();var r=l.getChunkSource().randomState();WellInteraction.require(g.wetlandHutDefinition()==0&&g.wetlandHutInitializationNanos()==0,"Old save remains opted out without hut planning cost");var ops=net.minecraft.resources.RegistryOps.create(com.mojang.serialization.JsonOps.INSTANCE,l.registryAccess());var saved=RealisticGenerator.CODEC.codec().encodeStart(ops,g).getOrThrow().getAsJsonObject();WellInteraction.require(saved.get("shape_version").getAsInt()==93&&!saved.has("wetland_huts"),"Saved93 keeps93 without new fields");
  for(int v:new int[]{88,89,90,91,92,93}){var input=saved.deepCopy();input.addProperty("shape_version",v);boolean treasure=v==89||v==90||v==92||v==93,ship=v==90||v==93,gate=v>=91;if(!treasure){input.remove("small_discovery_definition");input.remove("treasure_cache");}if(!ship)input.remove("shipwrecks");if(!gate)input.remove("desert_waygates");var old=RealisticGenerator.CODEC.codec().parse(ops,input).getOrThrow();WellInteraction.require(old.wetlandHutDefinition()==0&&old.discoveryDefinition()==(treasure?1:0)&&old.shipwreckDefinition()==(ship?1:0)&&old.waygateDefinition()==(gate?1:0),"Exact legacy feature combination"+v);}
  var q=Files.readString(Path.of("saved-edit.txt")).split(",");var edit=new BlockPos(Integer.parseInt(q[0].trim()),Integer.parseInt(q[1].trim()),Integer.parseInt(q[2].trim()));WellInteraction.require(l.getBlockState(edit).is(Blocks.OAK_PLANKS),"Existing shipwreck repair preserved");var pos=Files.readString(Path.of("view.txt")).split(",");int x=Integer.parseInt(pos[0]),z=Integer.parseInt(pos[2]);var holder=l.registryAccess().lookupOrThrow(Registries.STRUCTURE).getOrThrow(net.minecraft.world.level.levelgen.structure.BuiltinStructures.SHIPWRECK_BEACHED);var chunk=l.getChunk(x>>4,z>>4);var start=l.structureManager().getStartForStructure(holder.value(),chunk);var tag=start.getPieces().getFirst().createTag(net.minecraft.world.level.levelgen.structure.pieces.StructurePieceSerializationContext.fromLevel(l));WellInteraction.require(tag.toString().contains("coastal_sloop_v2_"),"Existing native piece ID remains v2");
  var row=Files.readString(Path.of("shipwreck.json"));var oldReport=com.google.gson.JsonParser.parseString(row).getAsJsonObject();var supply=oldReport.getAsJsonArray("chests").get(0).getAsJsonObject().get("position").getAsString().split(",");var chestPos=new BlockPos(Integer.parseInt(supply[0].trim()),Integer.parseInt(supply[1].trim()),Integer.parseInt(supply[2].trim()));var chest=(net.minecraft.world.level.block.entity.ChestBlockEntity)l.getBlockEntity(chestPos);chest.unpackLootTable(null);WellInteraction.require(chest.getItem(0).isEmpty(),"Removed old loot is not recreated");
  PreviewNativeStorageChecks.check(l);
  server.saveEverything(false,true,true);Files.writeString(Path.of("legacy-hut-check.json"),"{\"schema93Retained\":true,\"legacy88to93Flags\":true,\"noHutPlanning\":true,\"shipwreckRepairAndLoot\":true,\"nativeTemplateIdPreserved\":true,\"deferredPreviewPixelsAndProgressNativeStorage\":true}");Files.writeString(Path.of("result.txt"),"PASS");
 }catch(Throwable e){blockbranch.Blockbranch.LOGGER.error("WETLAND_HUT_LEGACY_FAIL",e);try{Files.writeString(Path.of("result.txt"),"FAIL "+e);}catch(Exception ignored){}}finally{server.halt(false);}});}
}
